using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
namespace LunarRelay {
[Serializable] public class DecorPlacement {public string Id;public int Kind;public Vector3 Position;public Quaternion Rotation;}
[Serializable] public class DecorProfile {public int Credits;public int[] Owned=new int[3];public List<string> Rewards=new List<string>();public List<DecorPlacement> Placed=new List<DecorPlacement>();}
public sealed class PlacedDecor:MonoBehaviour {public string Id;public int Kind;}
public sealed partial class Simulation {public string RewardRunId;}
public sealed partial class GameSession {
 public bool DecorPlacementActive=>placingKind>=0;
 DecorProfile decorProfile;readonly Dictionary<string,GameObject> decorObjects=new Dictionary<string,GameObject>();readonly Texture2D[] decorIcons=new Texture2D[3];bool shopPage;int placingKind=-1;GameObject decorPreview;string movingDecor;float decorAngle;bool decorValid;Material ghostMaterial;Vector2 decorScroll;
 readonly int[] decorPrices={50,40,70};
 string DecorPath=>string.IsNullOrEmpty(SmokePath)?Path.Combine(Application.persistentDataPath,"lunar-decor-v1.json"):Path.Combine(SmokePath,"test-decor-profile.json");
 string DecorName(int k)=>k==0?UI("Космический светильник","Space lamp"):k==1?UI("Настольное растение","Desk plant"):UI("Экран с Землёй","Earth wall display");
 void InitDecor(){if(decorProfile!=null)return;try{decorProfile=File.Exists(DecorPath)?JsonUtility.FromJson<DecorProfile>(File.ReadAllText(DecorPath)):new DecorProfile();if(decorProfile==null||decorProfile.Owned==null||decorProfile.Owned.Length!=3||decorProfile.Rewards==null||decorProfile.Placed==null)throw new Exception();}catch{decorProfile=new DecorProfile();}foreach(var p in decorProfile.Placed){if(p.Kind<0||p.Kind>2||string.IsNullOrEmpty(p.Id)||decorObjects.ContainsKey(p.Id))continue;var g=DecorModels.Create(p.Kind);g.transform.SetPositionAndRotation(p.Position,p.Rotation);var d=g.AddComponent<PlacedDecor>();d.Id=p.Id;d.Kind=p.Kind;decorObjects[p.Id]=g;}StartCoroutine(DecorThumbnails());}
 void SaveDecor(){try{var path=DecorPath;Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path+".tmp",JsonUtility.ToJson(decorProfile,true));if(File.Exists(path))File.Replace(path+".tmp",path,path+".bak");else File.Move(path+".tmp",path);}catch(Exception e){Debug.LogWarning("Decoration save: "+e.Message);}}
 bool Reward(string key,int amount){string claim=Sim.RewardRunId+"/"+key;if(decorProfile.Rewards.Contains(claim))return false;decorProfile.Rewards.Add(claim);decorProfile.Credits+=amount;SaveDecor();creditNoticeAmount=amount;creditNoticeUntil=Time.unscaledTime+4;return true;}
 void CheckRewards(){if(!started||!Sim.Expanded||Sim.Aborted)return;if(string.IsNullOrEmpty(Sim.RewardRunId))Sim.RewardRunId=Guid.NewGuid().ToString("N");if(Sim.ScrubberRepaired&&Sim.AirOn&&Sim.MainPower)Reward("air",10);if(Sim.ArrayRepaired&&Sim.MainPower)Reward("power",10);if(Sim.Packs>=3&&Sim.ShieldLitres[0]>=4&&Sim.ShieldLitres[1]>=4&&Sim.ShieldLitres[2]>=4)Reward("shelter",10);}
 int AvailableDecor(int k)=>decorProfile.Owned[k]-decorProfile.Placed.FindAll(p=>p.Kind==k).Count;
 bool BuyDecor(int k){if(k<0||k>2||decorProfile.Credits<decorPrices[k])return false;decorProfile.Credits-=decorPrices[k];decorProfile.Owned[k]++;SaveDecor();return true;}
 System.Collections.IEnumerator DecorThumbnails(){for(int k=0;k<3;k++){var model=DecorModels.Create(k);foreach(var t in model.GetComponentsInChildren<Transform>())t.gameObject.layer=30;foreach(var light in model.GetComponentsInChildren<Light>())light.enabled=false;model.transform.position=new Vector3(0,-900,0);var go=new GameObject("Shop product camera");var cam=go.AddComponent<Camera>();cam.cullingMask=1<<30;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.035f,.07f,.10f);cam.orthographic=true;cam.orthographicSize=k==2?.4f:.32f;cam.nearClipPlane=.01f;cam.farClipPlane=4;cam.transform.position=model.transform.position+new Vector3(.5f,.44f,1);cam.transform.LookAt(model.transform.position+Vector3.up*(k==2?0:.17f));var lamp=new GameObject("Product softbox").AddComponent<Light>();lamp.type=LightType.Directional;lamp.cullingMask=1<<30;lamp.intensity=1.8f;lamp.transform.rotation=Quaternion.Euler(35,205,0);var rt=new RenderTexture(320,240,24);cam.targetTexture=rt;var active=RenderTexture.active;cam.Render();RenderTexture.active=rt;var icon=new Texture2D(320,240,TextureFormat.RGB24,false);icon.ReadPixels(new Rect(0,0,320,240),0,0);icon.Apply();decorIcons[k]=icon;RenderTexture.active=active;cam.targetTexture=null;rt.Release();Destroy(rt);Destroy(model);Destroy(go);Destroy(lamp.gameObject);yield return null;}}
 void ShopScreen(){Text(208,272,1000,32,UI("МАГАЗИН И УКРАШЕНИЯ","SHOP & DECORATION")+"     "+decorProfile.Credits+" LC",heading,cyan);for(int k=0;k<3;k++){float x=208+k*338;Box(x,319,320,305,surface);if(decorIcons[k])GUI.DrawTexture(new Rect(x+10,326,300,155),decorIcons[k],ScaleMode.ScaleToFit);Text(x+14,485,290,44,DecorName(k),body);Text(x+14,532,290,25,decorPrices[k]+" LC · "+UI("На складе: ","In storage: ")+AvailableDecor(k),small,cyan);GUI.enabled=decorProfile.Credits>=decorPrices[k];if(Button(x+14,568,140,42,UI("Купить","Buy")))BuyDecor(k);GUI.enabled=AvailableDecor(k)>0;if(Button(x+164,568,140,42,UI("Разместить","Place")))BeginDecor(k,null);GUI.enabled=true;}
 Text(208,640,990,25,UI("УСТАНОВЛЕННЫЕ ПРЕДМЕТЫ","PLACED ITEMS"),small,cyan);decorScroll=TouchScrollView(new Rect(208,674,1000,120),decorScroll,new Rect(0,0,970,Mathf.Max(110,decorProfile.Placed.Count*48)));for(int i=0;i<decorProfile.Placed.Count;i++){var p=decorProfile.Placed[i];Text(0,i*48+8,460,32,DecorName(p.Kind),small);if(Button(480,i*48,225,40,UI("Переместить","Move")))BeginDecor(p.Kind,p.Id);if(Button(720,i*48,225,40,UI("Убрать","Store"))){StoreDecor(p.Id);break;}}EndTouchScrollView();}
 void StoreDecor(string id){if(decorObjects.TryGetValue(id,out var go))Destroy(go);decorObjects.Remove(id);decorProfile.Placed.RemoveAll(p=>p.Id==id);SaveDecor();}
 void BeginDecor(int kind,string move){CancelDecor();if(move==null&&AvailableDecor(kind)<=0)return;placingKind=kind;movingDecor=move;if(move!=null&&decorObjects.TryGetValue(move,out var existing))existing.SetActive(false);decorPreview=DecorModels.Create(kind);foreach(var c in decorPreview.GetComponentsInChildren<Collider>())c.enabled=false;foreach(var light in decorPreview.GetComponentsInChildren<Light>())light.enabled=false;if(!ghostMaterial){ghostMaterial=new Material(Resources.Load<Shader>("DecorGhost"));ghostMaterial.renderQueue=3000;}foreach(var renderer in decorPreview.GetComponentsInChildren<Renderer>())renderer.sharedMaterial=ghostMaterial;showStatus=showInventory=showLog=paused=false;UpdateCursor();}
 void CancelDecor(){if(decorPreview)Destroy(decorPreview);if(movingDecor!=null&&decorObjects.TryGetValue(movingDecor,out var old))old.SetActive(true);decorPreview=null;movingDecor=null;placingKind=-1;}
 bool AllowedDecorNormal(int kind,Vector3 normal)=>kind==2?Mathf.Abs(normal.y)<.25f:normal.y>.92f;
 bool PlacementClear(Vector3 position,Quaternion rotation,int kind){var center=kind==2?new Vector3(0,0,.025f):new Vector3(0,.18f,0);var half=kind==2?new Vector3(.308f,.193f,.033f):new Vector3(.118f,.178f,.118f);return Physics.OverlapBox(position+rotation*center,half,rotation,~((1<<2)|(1<<30)|(1<<31)),QueryTriggerInteraction.Ignore).Length==0;}
 void DecorUpdate(){if(decorProfile==null)InitDecor();CheckRewards();if(!Playing){if(decorPreview)CancelDecor();return;}bool confirm=mobilePlace,cancel=mobileCancel;mobilePlace=mobileCancel=false;var mouse=Application.isMobilePlatform?null:Mouse.current;if(mouse==null&&!Application.isMobilePlatform)return;if(placingKind<0){if(Keyboard.current!=null&&Keyboard.current.eKey.wasPressedThisFrame&&Physics.Raycast(Player.View.transform.position,Player.View.transform.forward,out var hit,2.8f,~(1<<2))){var d=hit.collider.GetComponent<PlacedDecor>();if(d)BeginDecor(d.Kind,d.Id);}return;}
 if(mouse!=null)decorAngle+=mouse.scroll.ReadValue().y/120*15;if(cancel||(mouse!=null&&mouse.rightButton.wasPressedThisFrame)){CancelDecor();return;}decorValid=false;var ray=new Ray(Player.View.transform.position,Player.View.transform.forward);if(Physics.Raycast(ray,out var surface,3,~((1<<2)|(1<<30)|(1<<31)),QueryTriggerInteraction.Ignore)){bool horizontal=surface.normal.y>.92f,wall=Mathf.Abs(surface.normal.y)<.25f;var q=placingKind==2?Quaternion.LookRotation(surface.normal,Vector3.up)*Quaternion.AngleAxis(decorAngle,Vector3.forward):Quaternion.Euler(0,decorAngle,0);var p=surface.point+surface.normal*.012f;decorPreview.transform.SetPositionAndRotation(p,q);bool onBase=surface.point.y>.15f&&surface.point.y<2.5f&&((surface.point.x*surface.point.x+surface.point.z*surface.point.z<2.8f)|| (surface.point.x>=-10&&surface.point.x<-.9f&&Mathf.Abs(surface.point.z)<2.3f));decorValid=onBase&&!Outside&&!surface.collider.GetComponentInParent<StationAction>()&&AllowedDecorNormal(placingKind,surface.normal)&&PlacementClear(p,q,placingKind);}else decorPreview.transform.position=ray.GetPoint(1.5f);ghostMaterial.SetColor("_BaseColor",decorValid?new Color(.25f,.8f,.8f,.42f):new Color(.9f,.3f,.15f,.4f));if(decorValid&&(confirm||(mouse!=null&&mouse.leftButton.wasPressedThisFrame))){int kind=placingKind;string id=movingDecor??Guid.NewGuid().ToString("N");var p=decorProfile.Placed.Find(a=>a.Id==id);if(p==null){p=new DecorPlacement{Id=id,Kind=kind};decorProfile.Placed.Add(p);}p.Position=decorPreview.transform.position;p.Rotation=decorPreview.transform.rotation;if(decorObjects.TryGetValue(id,out var old))Destroy(old);var g=DecorModels.Create(kind);g.transform.SetPositionAndRotation(p.Position,p.Rotation);var marker=g.AddComponent<PlacedDecor>();marker.Id=id;marker.Kind=kind;decorObjects[id]=g;movingDecor=null;CancelDecor();SaveDecor();}}
 void DecorHUD(){if(Application.isMobilePlatform){if(placingKind>=0)Text(470,660,500,55,DecorName(placingKind)+" · "+(decorValid?UI("Можно установить","Ready to place"):UI("Выберите свободную поверхность","Aim at a clear surface")),small,decorValid?cyan:amber);return;}if(placingKind>=0)Text(400,680,700,60,DecorName(placingKind)+" · "+UI("ЛКМ установить · колесо повернуть · ПКМ отменить","LMB place · wheel rotate · RMB cancel"),body,decorValid?cyan:amber);else if(Physics.Raycast(Player.View.transform.position,Player.View.transform.forward,out var hit,2.8f,~(1<<2))&&hit.collider.GetComponent<PlacedDecor>())Text(510,650,500,28,UI("E — переместить украшение · убрать через Shop","E — move decoration · store through Shop"),small,cyan);}
}
